            ))}
            {referenced.map((relation) => (
              <RelationRow
                key={`referenced-${getRelationMemo(relation, "referenced")?.name}`}
                relation={relation}
                direction="referenced"
                snippet={relationSnippet(relation, "referenced")}
              />
            ))}
          </div>
        </Section>
      )}

      {headings.length > 0 && (
        <Section label={t("memo.outline")}>
          <MemoOutline headings={headings} />
        </Section>
      )}

      {sharePanelOpen && <MemoSharePanel memoName={memo.name} open={sharePanelOpen} onClose={() => setSharePanelOpen(false)} />}
    </aside>
  );
};
"},{"node":"VisibilitySelector","qualified_name":"bench-repo.web.src.components.MemoEditor.Toolbar.VisibilitySelector.VisibilitySelector","label":"Function","file":"web/src/components/MemoEditor/Toolbar/VisibilitySelector.tsx","start_line":9,"end_line":52,"in_degree":2,"out_degree":9,"match_lines":[9,15,16,17,34,41],"source":"const VisibilitySelector = (props: VisibilitySelectorProps) => {
  const { value, onChange } = props;
  const compact = props.size === "compact";
  const t = useTranslate();

  const visibilityOptions = [
    { value: Visibility.PRIVATE, label: t("memo.visibility.private"), description: t("memo.visibility.private-description") },
    { value: Visibility.PROTECTED, label: t("memo.visibility.protected"), description: t("memo.visibility.protected-description") },
    { value: Visibility.PUBLIC, label: t("memo.visibility.public"), description: t("memo.visibility.public-description") },
  ] as const;

  const currentLabel = visibilityOptions.find((option) => option.value === value)?.label || "";

  return (
