"},{"node":"checkAttachmentAccess","qualified_name":"bench-repo.server.router.api.v1.checkAttachmentAccess","label":"Method","file":"server/router/api/v1/attachment_service.go","start_line":422,"end_line":455,"in_degree":1,"out_degree":3,"match_lines":[445,451],"source":"func (s *APIV1Service) checkAttachmentAccess(ctx context.Context, attachment *store.Attachment) error {
	user, _ := s.fetchCurrentUser(ctx)

	// For unlinked attachments, only the creator can access.
	if attachment.MemoID == nil {
		if user == nil {
			return status.Errorf(codes.Unauthenticated, "user not authenticated")
		}
		if attachment.CreatorID != user.ID && !isSuperUser(user) {
			return status.Errorf(codes.PermissionDenied, "permission denied")
		}
		return nil
	}

	// For linked attachments, check memo visibility.
	memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: attachment.MemoID})
	if err != nil {
		return status.Errorf(codes.Internal, "failed to get memo: %v", err)
	}
	if memo == nil {
		return status.Errorf(codes.NotFound, "memo not found")
	}

	if memo.Visibility == store.Public {
		return nil
	}
	if user == nil {
		return status.Errorf(codes.Unauthenticated, "user not authenticated")
	}
	if memo.Visibility == store.Private && memo.CreatorID != user.ID && !isSuperUser(user) {
		return status.Errorf(codes.PermissionDenied, "permission denied")
	}
	return nil
}
"},{"node":"canUserAccessMentionContext","qualified_name":"bench-repo.server.router.api.v1.canUserAccessMentionContext","label":"Function","file":"server/router/api/v1/memo_mention_helpers.go","start_line":56,"end_line":72,"in_degree":1,"out_degree":0,"match_lines":[62,67],"source":"func canUserAccessMentionContext(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
	if target == nil || memo == nil {
		return false
	}

	if relatedMemo != nil {
		if relatedMemo.Visibility == store.Private && target.ID != relatedMemo.CreatorID {
			return false
		}
	}

	if memo.Visibility == store.Private && target.ID != memo.CreatorID {
		return false
	}

	return true
}
"},{"node":"shouldSkipMentionInbox","qualified_name":"bench-repo.server.router.api.v1.shouldSkipMentionInbox","label":"Function","file":"server/router/api/v1/memo_mention_helpers.go","start_line":74,"end_line":89,"in_degree":1,"out_degree":1,"match_lines":[84],"source":"func shouldSkipMentionInbox(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
	if target == nil || memo == nil {
		return true
	}

	if target.ID == memo.CreatorID {
		return true
	}

	// Comment creation already generates a memo-comment inbox item for the parent creator.
	if relatedMemo != nil && target.ID == relatedMemo.CreatorID && memo.Visibility != store.Private && memo.CreatorID != relatedMemo.CreatorID {
		return true
	}

	return !canUserAccessMentionContext(target, memo, relatedMemo)
}
